    if (!fs.existsSync(previewPath)) continue;
    const html = fs.readFileSync(previewPath, "utf8");
    const scripts = [];
    const scriptRe = /<script\b[^>]*\bsrc\s*=\s*["']([^"']+)["'][^>]*>\s*<\/script>/gi;
